import { View, Text, SectionList, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SECTIONS = [
  { title: "Электроник", data: ["Чихэвч", "Гар цаг"] },
  { title: "Хувцас", data: ["Гутал", "Цүнх"] },
];

function App() {
  const [query, setQuery] = useState("");
  // энд бичнэ үү: query-ээр SECTIONS-ийг шүүж visible бүтээ
  const visible = SECTIONS;
  return (
    <View style={styles.screen}>
      <TextInput nativeID="search" style={styles.input} placeholder="Бараа хайх..." value={query} onChangeText={setQuery} />
      <SectionList
        style={styles.list}
        sections={visible}
        keyExtractor={(item, i) => item + i}
        renderSectionHeader={({ section }) => (
          <View testID="section-header" style={styles.header}>
            <Text style={styles.headerText}>{section.title}</Text>
          </View>
        )}
        renderItem={({ item }) => (
          <View testID="product" style={styles.row}>
            <Text>{item}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  input: { margin: 16, padding: 12, borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, backgroundColor: "#fff" },
  list: { flex: 1 },
  header: { padding: 12, backgroundColor: "#e0e7ff" },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
});

registerRootComponent(App);

